def shard(tenant):
    return tenant.created_at.strftime('%Y-%m')

def serve(request):
    results = []
    for dependency in request.dependencies:  # six mandatory services
        for attempt in range(3):
            try:
                results.append(dependency.call(timeout=2))
                break
            except TimeoutError:
                if attempt == 2:
                    raise
    return results

